// Kettlebell Bot — preview-only showcase timelines.
//
// These are not referenced by the state machine. They exist so a single APNG can
// demonstrate the whole system: the full turnaround, and the emotional range.
// The emotion reel is generated by sampling the real mood loops at a
// characteristic frame, so it can never drift from the shipped acting.

import { ch, E, loopAnim, mergeTracks } from "./motion.mjs";
import { MOOD_CHANNELS } from "./moods.mjs";
import { sampleFacing, turnTracks } from "./turn.mjs";

/** Value of a numeric track at `frame` (linear read of the authored curve). */
function valueAt(track, frame) {
  const kf = track.keyframes;
  if (frame <= kf[0].frame) return kf[0].value;
  if (frame >= kf.at(-1).frame) return kf.at(-1).value;
  for (let i = 0; i < kf.length - 1; i += 1) {
    const a = kf[i];
    const b = kf[i + 1];
    if (frame >= a.frame && frame <= b.frame) {
      if (b.easing === "hold") return a.value;
      const t = (frame - a.frame) / (b.frame - a.frame || 1);
      return a.value + (b.value - a.value) * t;
    }
  }
  return kf.at(-1).value;
}

/** Snapshot every mood channel (plus both solo refs) of an animation. */
export function samplePose(anim, frame) {
  const values = {};
  const solo = {};
  for (const track of anim.tracks) {
    const key = `${track.target}|${track.property}`;
    if (track.property === "soloActive") {
      let ref = track.keyframes[0].ref;
      for (const k of track.keyframes) if (k.frame <= frame) ref = k.ref;
      solo[track.target] = ref;
      continue;
    }
    values[key] = Number(valueAt(track, frame).toFixed(4));
  }
  return { values, solo };
}

/**
 * Emotion reel: hold each mood's signature pose, snap to the next.
 * @param {Array<{anim: object, frame: number, facing: number}>} beats
 */
export function buildEmotionShowcase(beats, { hold = 28, move = 13 } = {}) {
  const channels = new Map();
  for (const [target, property, rest] of MOOD_CHANNELS) {
    if (property === "soloActive") continue;
    channels.set(`${target}|${property}`, { target, property, rest, keys: [] });
  }
  const soloKeys = { EyeLSolo: [], EyeRSolo: [] };
  const facingKeys = [];

  let frame = 0;
  for (const [index, beat] of beats.entries()) {
    const { values, solo } = samplePose(beat.anim, beat.frame);
    const arrive = index === 0 ? 0 : frame + move;
    for (const entry of channels.values()) {
      const value = values[`${entry.target}|${entry.property}`] ?? entry.rest;
      entry.keys.push([arrive, value, index === 0 ? undefined : E.back]);
      entry.keys.push([arrive + hold, value, E.hold]);
    }
    for (const group of ["EyeLSolo", "EyeRSolo"]) {
      const ref = solo[group];
      if (ref && soloKeys[group].at(-1)?.[1] !== ref) soloKeys[group].push([Math.max(0, arrive - 2), ref]);
    }
    facingKeys.push({ frame: arrive, facing: beat.facing ?? 0, ease: index === 0 ? "linear" : "outBack" });
    facingKeys.push({ frame: arrive + hold, facing: beat.facing ?? 0, ease: "linear" });
    frame = arrive + hold;
  }

  // Return to the first pose so the reel loops cleanly.
  const first = samplePose(beats[0].anim, beats[0].frame);
  const end = frame + move;
  for (const entry of channels.values()) {
    entry.keys.push([end, first.values[`${entry.target}|${entry.property}`] ?? entry.rest, E.back]);
  }
  for (const group of ["EyeLSolo", "EyeRSolo"]) {
    const ref = first.solo[group];
    if (ref) soloKeys[group].push([Math.max(0, end - 2), ref]);
  }
  facingKeys.push({ frame: end, facing: beats[0].facing ?? 0, ease: "outBack" });

  const tracks = [...channels.values()].map((entry) => ch(entry.target, entry.property, entry.keys));
  for (const group of ["EyeLSolo", "EyeRSolo"]) {
    tracks.push({
      target: group,
      property: "soloActive",
      keyframes: soloKeys[group].map(([f, ref]) => ({ frame: f, ref })),
    });
  }
  tracks.push(...turnTracks(sampleFacing(facingKeys, 4)));
  return loopAnim("showcase_emotions", end, mergeTracks(tracks));
}

/** Turnaround reel with the body kept alive underneath the rotation. */
export function buildTurnShowcase() {
  const d = 336;
  const facing = [
    { frame: 0, facing: 0 },
    { frame: 20, facing: 0, ease: "linear" },
    { frame: 52, facing: 45, ease: "inOut", dyn: { lean: -1.6, lift: -3 } },
    { frame: 74, facing: 45, ease: "linear", dyn: { lean: -1.6, lift: -3 } },
    { frame: 106, facing: 90, ease: "inOut", dyn: { lean: -2.2, lift: -4 } },
    { frame: 128, facing: 90, ease: "linear", dyn: { lean: -2.2, lift: -4 } },
    { frame: 168, facing: 180, ease: "inOut", dyn: { lift: -2 } },
    { frame: 192, facing: 180, ease: "linear", dyn: { lift: -2 } },
    { frame: 232, facing: 270, ease: "inOut", dyn: { lean: 2.2, lift: -4 } },
    { frame: 254, facing: 270, ease: "linear", dyn: { lean: 2.2, lift: -4 } },
    { frame: 286, facing: 315, ease: "inOut", dyn: { lean: 1.6, lift: -3 } },
    { frame: 306, facing: 315, ease: "linear", dyn: { lean: 1.6, lift: -3 } },
    { frame: 336, facing: 360, ease: "inOut" },
  ];
  return loopAnim("showcase_turnaround", d, [
    ...turnTracks(sampleFacing(facing, 4)),
    ch("Char", "y", [[0, 0], [84, -4, E.loop], [168, 0, E.loop], [252, -4, E.loop], [336, 0, E.loop]]),
    ch("Char", "scaleY", [[0, 1], [84, 1.012, E.loop], [168, 1, E.loop], [252, 1.012, E.loop], [336, 1, E.loop]]),
    ch("Char", "scaleX", [[0, 1], [84, 0.99, E.loop], [168, 1, E.loop], [252, 0.99, E.loop], [336, 1, E.loop]]),
    ch("HandlePivot", "rotation", [[0, 0], [70, 1.6, E.loop], [180, -1.6, E.loop], [300, 1, E.loop], [336, 0, E.loop]]),
    ch("EyeLSolo", "scaleY", [[0, 1], [28, 1, E.hold], [32, 0.1, E.in], [38, 1.08, E.out], [42, 1, E.out], [300, 1, E.hold], [304, 0.1, E.in], [310, 1, E.out], [336, 1, E.hold]]),
    ch("EyeRSolo", "scaleY", [[0, 1], [29, 1, E.hold], [33, 0.1, E.in], [39, 1.08, E.out], [43, 1, E.out], [301, 1, E.hold], [305, 0.1, E.in], [311, 1, E.out], [336, 1, E.hold]]),
  ]);
}
